import { Module } from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';
import { JwtAuthGuard } from './auth/jwt-auth.guard';
import { AuthModule } from './auth/auth.module';

@Module({
  imports: [AuthModule],
  providers: [
    {
      provide: APP_GUARD,
      useClass: JwtAuthGuard,
    },
  ],
})
export class AppModule {}
```

Note this is registered in a module's `providers` array, **not** via `app.useGlobalGuards(new JwtAuthGuard(...))` in `main.ts`. The `APP_GUARD` token form keeps the guard inside Nest's own DI graph, which is exactly why the guard above can inject `Reflector` and `JwtService` — the `useGlobalGuards()` call from your bootstrap file instantiates the guard outside the container and gives you no injection.

